parameters.jsCode:
const ev = $input.first().json.output ?? $input.first().json;
const app = $('prepare application').first().json;
const profile = $('Extract Candidate Profile').first().json.output || {};
const cv = (app.cvText || '').toLowerCase();
const problems = [];

if (!Number.isInteger(ev.score) || ev.score < 0 || ev.score > 100) 
  problems.push('score must be a whole number from 0 to 100');
if (!['interview', 'maybe', 'reject'].includes(ev.recommendation)) 
  problems.push('recommendation must be interview, maybe or reject');
if (ev.recommendation === 'interview' && ev.score < 70) 
  problems.push('interview needs a score of 70 or more');
if (ev.recommendation === 'reject' && ev.score >= 40) 
  problems.push('reject needs a score below 40');
if (!(ev.matched_requirements || []).length && !(ev.missing_requirements || []).length) 
  problems.push('the evaluation lists no requirements');

const unverified = (profile.skills || []).filter(s => 
  !cv.includes(String(s).toLowerCase().split(' ')[0]));
if (unverified.length > 2) problems.push('skills not found in the CV: ' + unverified.join(', '));

const { cvText, jobRequirements, ...applicant } = app;
return [{ json: { ...applicant, ...ev, yearsExperience: profile.years_experience ?? '', topSkills: (profile.skills || []).slice(0, 6).join(', '), valid: problems.length === 0, problems: problems.join('; ') } }];
